def launch(script,arguments,approved_sha256,certificate):
    if not isinstance(arguments,list) or len(arguments)>32 or any(not isinstance(v,str) or '\0' in v or len(v)>256 for v in arguments) or not isinstance(approved_sha256,str) or not re.fullmatch('[0-9a-f]{64}',approved_sha256):raise ValueError('approved launch input')
    descriptor=os.open(script,os.O_RDONLY|os.O_NOFOLLOW)
    try:
        meta=os.fstat(descriptor)
        if not stat.S_ISREG(meta.st_mode) or meta.st_uid!=os.geteuid() or meta.st_mode&0o022 or meta.st_size>16384:raise ValueError('private approved script')
        with os.fdopen(descriptor,'rb',closefd=False) as source:raw=source.read(16385)
    finally:os.close(descriptor)
    if len(raw)>16384 or hashlib.sha256(raw).hexdigest()!=approved_sha256:raise ValueError('script approval mismatch')
