    except UnicodeDecodeError as error:raise ValueError('script encoding') from error
    certificate=str(pathlib.Path(certificate).absolute())
    if not pathlib.Path(certificate).is_file():raise ValueError('certificate material absent')
    env={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8','SSL_CERT_FILE':certificate}
    result=subprocess.run(['/bin/bash','--noprofile','--norc','-c',code,'opsforge-task',*arguments],env=env,stdin=subprocess.DEVNULL,capture_output=True,text=True,encoding='utf8',timeout=2)
